    "ಕನ್ನಡ": "ತೀವ್ರ ಶಾಖ (35–46°C) ಮತ್ತು ಕಡಿಮೆ ಮಳೆಯನ್ನು (150–300 ಮಿ.ಮೀ) ತಡೆದುಕೊಳ್ಳುತ್ತದೆ; ಮಣ್ಣಿನ ಸವೆತವನ್ನು ತಡೆಯುತ್ತದೆ",
