    "हिन्दी": "⭐ ग्रामीण दिल्ली (नजफगढ़, अलीपुर, बवाना बेल्ट में 100+ वर्षों से) में उगाई जाने वाली पारंपरिक शीतकालीन अनाज की मुख्य फसल",
    "ಕನ್ನಡ": "⭐ ಗ್ರಾಮೀಣ ದೆಹಲಿಯಾದ್ಯಂತ (ನಜಾಫ್‌ಗಢ, ಅಲಿಪುರ್, ಬವಾನಾ ಪ್ರದೇಶಗಳಲ್ಲಿ 100+ ವರ್ಷಗಳಿಂದ) ಬೆಳೆಯಲಾಗುವ ಸಾಂಪ್ರದಾಯಿಕ ಚಳಿಗಾಲದ ಪ್ರಮುಖ ಧಾನ್ಯ",
    "தமிழ்": "⭐ கிராமப்புற டெல்லி முழுவதும் (நஜஃப்கர், அலிபூர், பவானா பகுதிகளில் 100+ ஆண்டுகளாக) பயிரிடப்படும் பாரம்பரிய குளிர்கால தானியம்",
    "తెలుగు": "⭐ గ్రామీణ ఢిల్లీ అంతటా (నజాఫ్‌గఢ్, అలీపూర్, బవానా ప్రాంతాలలో 100+ ఏళ్లుగా) పండిస్తున్న సాంప్రదాయ శీతాకాల ఆహార ధాన్యం",
    "मराठी": "⭐ ग्रामीण दिल्लीत (नजफगड, अलिपूर, बवाना पट्ट्यात १००+ वर्षांपासून) पिकवले जाणारे पारंपारिक हिवाळी मुख्य अन्नधान्य",
